Link: https://patch.msgid.link/20260408121252.2249051-21-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The original code in rxrpc_process_event for the RESPONSE packet case did not check the connection state under the lock before proceeding with response verification and security initialization. After the state transition, it also checked `conn->state` without holding the lock, which was racy. This allowed duplicate or late RESPONSE packets to re-enter the setup path even after the connection had already left the RXRPC_CONN_SERVICE_CHALLENGING state, causing potential corruption.

Here is the patch:
  */
 static int rxrpc_process_event(struct rxrpc_connection *conn,
 			       struct sk_buff *skb)
 {
 	struct rxrpc_skb_priv *sp = rxrpc_skb(skb);
+	bool secured = false;
 	int ret;

 	if (conn->state == RXRPC_CONN_ABORTED)
 		return -ECONNABORTED;

 	_enter("{%d},{%u,%%%u},", conn->debug_id, sp->hdr.type, sp->hdr.serial);

 	switch (sp->hdr.type) {
 	case RXRPC_PACKET_TYPE_CHALLENGE:
 		ret = conn->security->respond_to_challenge(conn, skb);
 		sp->chall.conn = NULL;
 		rxrpc_put_connection(conn, rxrpc_conn_put_challenge_input);
 		return ret;

 	case RXRPC_PACKET_TYPE_RESPONSE:
+		spin_lock_irq(&conn->state_lock);
+		if (conn->state != RXRPC_CONN_SERVICE_CHALLENGING) {
+			spin_unlock_irq(&conn->state_lock);
+			return 0;
+		}
+		spin_unlock_irq(&conn->state_lock);
+
 		ret = conn->security->verify_response(conn, skb);
 		if (ret < 0)
 			return ret;

 		ret = conn->security->init_connection_security(
 			conn, conn->key->payload.data[0]);
 		if (ret < 0)
 			return ret;

 		spin_lock_irq(&conn->state_lock);
-		if (conn->state == RXRPC_CONN_SERVICE_CHALLENGING)
+		if (conn->state == RXRPC_CONN_SERVICE_CHALLENGING) {
 			conn->state = RXRPC_CONN_SERVICE;
+			secured = true;
+		}
 		spin_unlock_irq(&conn->state_lock);

-		if (conn->state == RXRPC_CONN_SERVICE) {
+		if (secured) {
 			/* Offload call state flipping to the I/O thread.  As
 			 * we've already received the packet, put it on the
 			 * front of the queue.
 			 */
 			sp->poke_conn = rxrpc_get_connection(
 				conn, rxrpc_conn_get_poke_secured);
 			skb->mark = RXRPC_SKB_MARK_SERVICE_CONN_SECURED;
 			rxrpc_get_skb(skb, rxrpc_skb_get_conn_secured);
 			skb_queue_head(&conn->local->rx_queue, skb);
 			rxrpc_wake_up_io_thread(conn->local);
 		}
 		return 0;

 	default:
 		WARN_ON_ONCE(1);
 		return -EPROTO;
 	}
 }



